def transform(grid):
    h, w = len(grid), len(grid[0])
    bottom = grid[-1]
    # Nonzero runs on the final row define the patterns.
    patterns = []
    i = 0
    while i < w:
        if bottom[i] == 0:
            i += 1
            continue
        j = i
        while j < w and bottom[j] != 0:
            j += 1
        patterns.append((i, bottom[i:j]))
        i = j

    out = [row[:] for row in grid]
    for r in range(h - 1):
        for c, value in enumerate(grid[r]):
            if value == 0:
                continue
            for _, pattern in patterns:
                if value in pattern:
                    start = c - pattern.index(value)
                    for k, color in enumerate(pattern):
                        pos = start + k
                        if 0 <= pos < w:
                            out[r][pos] = color
                    break
    return out
